// Fusionne les deux boîtes et agrège les 7 derniers jours par fournisseur.
function parseList(d) {
  let a = Array.isArray(d) ? d : (d.emails || d.threads || d.result || []);
  let f = [];
  for (const t of a) { if (Array.isArray(t && t.messages)) f.push(...t.messages); else f.push(t); }
  return f;
}
const louis = parseList($('Lire Fournisseurs').first().json).map(e => ({ ...e, _box: 'louis@orchidy.fr' }));
const olivier = parseList($('Lire Fournisseurs olivier').first().json).map(e => ({ ...e, _box: 'olivier@orchidy.fr' }));
const flat = [...louis, ...olivier];
const since = Date.now() - 7 * 24 * 3600 * 1000;
const bySupplier = {};
for (const e of flat) {
  const d = new Date(e.date || e.received_at || 0).getTime();
  if (d < since) continue;
  const key = e._box + ' | ' + String(e.sender || e.from || '(inconnu)');
  const g = bySupplier[key] || { count: 0, unread: 0, subjects: [], box: e._box };
  g.count++;
  if (!e.is_read) g.unread++;
  g.subjects.push('- ' + (e.subject || '(sans objet)').slice(0, 100));
  bySupplier[key] = g;
}
const keys = Object.keys(bySupplier).sort();
if (keys.length === 0) {
  return [{ json: { empty: true, to: 'louiscyrano@gmail.com',
    subject: '\ud83d\udcca Résumé hebdo fournisseurs — rien de nouveau',
    text: 'Aucun email fournisseur reçu cette semaine (dossiers Fournisseurs des deux boîtes).\n\n— Orchidy Mail Agent' } }];
}
let text = 'Récapitulatif de la semaine (dossiers Fournisseurs, boîtes louis@ et olivier@) :\n';
for (const k of keys) {
  const g = bySupplier[k];
  text += '\n\ud83d\udce9 [' + g.box + '] ' + k.split(' | ')[1] + ' — ' + g.count + ' email(s)' + (g.unread ? ' (' + g.unread + ' non lu(s))' : '') + '\n';
  text += g.subjects.join('\n') + '\n';
}
text += '\n— Orchidy Mail Agent';
const total = keys.reduce((a, k) => a + bySupplier[k].count, 0);
return [{ json: { empty: false, to: 'louiscyrano@gmail.com',
  subject: '\ud83d\udcca Résumé hebdo fournisseurs — ' + total + ' email(s) de ' + keys.length + ' fournisseur(s)',
  text } }];
